import{y as e,b as a,c as r,X as o}from"./chunks/vue.Bn9cO5I3.js";import"./app.tjc9Wtrh.js";import"./chunks/mermaid.DvhSlOLG.js";const g=JSON.parse('{"title":"Provider Adapter Contracts (G-RV-05)","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/PROVIDER_ADAPTER_CONTRACTS.md","filePath":"contracts/PROVIDER_ADAPTER_CONTRACTS.md","lastUpdated":1771753292000}'),d={name:"contracts/PROVIDER_ADAPTER_CONTRACTS.md"};function n(i,t,l,s,c,p){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="provider-adapter-contracts-g-rv-05" tabindex="-1">Provider Adapter Contracts (G-RV-05) <a class="header-anchor" href="#provider-adapter-contracts-g-rv-05" aria-label="Permalink to &quot;Provider Adapter Contracts (G-RV-05)&quot;">​</a></h1><p>undefined<strong>Purpose:</strong> Document output contracts for copilot, gemini, codex, and claude adapters. undefined<strong>Date:</strong> 2026-02-14 undefined<strong>Scope:</strong> WBS-X5 Provider Adapter Layer</p><hr><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>Provider adapters normalize raw agent output into <code>CanonicalStructuredMessage</code> (CSM). All four primary providers (copilot, gemini, codex, claude) use the same XML-based contract. Adapters are implemented in <code>src/thegent/contracts/adapters.py</code>.</p><table tabindex="0"><thead><tr><th>Provider</th><th>Adapter</th><th>Source Contract</th><th>Notes</th></tr></thead><tbody><tr><td>copilot</td><td>XMLOutputAdapter</td><td>task-tool-18 / xml-tags</td><td>GitHub Copilot CLI</td></tr><tr><td>gemini</td><td>XMLOutputAdapter</td><td>task-tool-18 / xml-tags</td><td>Google Gemini CLI</td></tr><tr><td>codex</td><td>XMLOutputAdapter</td><td>task-tool-18 / xml-tags</td><td>Codex proxy / cursor</td></tr><tr><td>claude</td><td>XMLOutputAdapter</td><td>task-tool-18 / xml-tags</td><td>Anthropic Claude CLI</td></tr><tr><td>cursor-agent</td><td>XMLOutputAdapter</td><td>task-tool-18 / xml-tags</td><td>Cursor agent</td></tr><tr><td>antigravity</td><td>XMLOutputAdapter</td><td>task-tool-18 / xml-tags</td><td>Proxy backend</td></tr></tbody></table><hr><h2 id="_2-shared-xml-protocol" tabindex="-1">2. Shared XML Protocol <a class="header-anchor" href="#_2-shared-xml-protocol" aria-label="Permalink to &quot;2. Shared XML Protocol&quot;">​</a></h2><p>All providers emit XML tags in stdout. The parser extracts balanced tags <code>&lt;TAG&gt;content&lt;/TAG&gt;</code> (case-insensitive).</p><h3 id="_2-1-supported-tags-→-csm-mapping" tabindex="-1">2.1 Supported Tags → CSM Mapping <a class="header-anchor" href="#_2-1-supported-tags-→-csm-mapping" aria-label="Permalink to &quot;2.1 Supported Tags → CSM Mapping&quot;">​</a></h3><table tabindex="0"><thead><tr><th>XML Tag</th><th>CSM Field</th><th>Notes</th></tr></thead><tbody><tr><td>STATUS, TASK_STATUS</td><td>status</td><td>pending, in_progress, completed, failed, blocked, cancelled, done→completed, skipped→cancelled</td></tr><tr><td>PROGRESS, TASK_PROGRESS, PERCENT_COMPLETE</td><td>progress</td><td>0–100 or 0.0–1.0; normalized to 0.0–1.0</td></tr><tr><td>TASK_ID, TASKID</td><td>task_id</td><td></td></tr><tr><td>OBJECTIVE, TASK_OBJECTIVE</td><td>objective</td><td></td></tr><tr><td>SUMMARY, TASK_SUMMARY, TASK_UPDATE, TASKUPDATE</td><td>summary</td><td></td></tr><tr><td>ACTIONS_COMPLETED</td><td>actions_completed</td><td>Newline-separated list</td></tr><tr><td>ISSUES, TASK_ISSUES</td><td>issues</td><td>Newline-separated list</td></tr><tr><td>NEXT_STEPS, TASK_NEXT_STEPS</td><td>next_steps</td><td>Newline-separated list</td></tr></tbody></table><h3 id="_2-2-status-normalization" tabindex="-1">2.2 Status Normalization <a class="header-anchor" href="#_2-2-status-normalization" aria-label="Permalink to &quot;2.2 Status Normalization&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pending, in_progress, completed, failed, blocked, cancelled</span></span>
<span class="line"><span>done → completed</span></span>
<span class="line"><span>skipped → cancelled</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h2 id="_3-per-provider-contract-notes" tabindex="-1">3. Per-Provider Contract Notes <a class="header-anchor" href="#_3-per-provider-contract-notes" aria-label="Permalink to &quot;3. Per-Provider Contract Notes&quot;">​</a></h2><h3 id="_3-1-copilot" tabindex="-1">3.1 Copilot <a class="header-anchor" href="#_3-1-copilot" aria-label="Permalink to &quot;3.1 Copilot&quot;">​</a></h3><ul><li>undefined<strong>CLI:</strong> <code>copilot</code> (GitHub Copilot CLI)</li><li>undefined<strong>Output:</strong> Stdout with XML tags; same tag set as task-tool-18</li><li>undefined<strong>Fallback:</strong> If no XML tags, <code>GenericOutputAdapter</code> or <code>extract_condensed</code> yields <code>source_contract=plain</code> with confidence 0.7</li></ul><h3 id="_3-2-gemini" tabindex="-1">3.2 Gemini <a class="header-anchor" href="#_3-2-gemini" aria-label="Permalink to &quot;3.2 Gemini&quot;">​</a></h3><ul><li>undefined<strong>CLI:</strong> <code>gemini</code> (Google Gemini CLI)</li><li>undefined<strong>Output:</strong> Stdout with XML tags; supports task-tool-18 and zen-rich-v1</li><li>undefined<strong>Fallback:</strong> Same as copilot</li></ul><h3 id="_3-3-codex" tabindex="-1">3.3 Codex <a class="header-anchor" href="#_3-3-codex" aria-label="Permalink to &quot;3.3 Codex&quot;">​</a></h3><ul><li>undefined<strong>CLI:</strong> <code>cursor agent</code> or codex proxy</li><li>undefined<strong>Output:</strong> Stdout with XML tags; cursor-agent format compatible with task-tool-18</li><li>undefined<strong>Fallback:</strong> Same as copilot</li></ul><h3 id="_3-4-claude" tabindex="-1">3.4 Claude <a class="header-anchor" href="#_3-4-claude" aria-label="Permalink to &quot;3.4 Claude&quot;">​</a></h3><ul><li>undefined<strong>CLI:</strong> <code>claude</code> (Anthropic Claude CLI)</li><li>undefined<strong>Output:</strong> Stdout with XML tags; same tag set as task-tool-18</li><li>undefined<strong>Fallback:</strong> Same as copilot</li></ul><hr><h2 id="_4-adapter-result-contract" tabindex="-1">4. Adapter Result Contract <a class="header-anchor" href="#_4-adapter-result-contract" aria-label="Permalink to &quot;4. Adapter Result Contract&quot;">​</a></h2><p>Every adapter returns <code>AdapterResult</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>csm</td><td>CanonicalStructuredMessage</td><td>Normalized output</td></tr><tr><td>confidence</td><td>float</td><td>0.0–1.0; 1.0 = full parse, 0.7 = validation issues, 0.3–0.5 = fallback</td></tr><tr><td>parse_errors</td><td>list[str]</td><td>parse_truncated, no_xml_tags_detected, or validation issues</td></tr><tr><td>source_provider</td><td>str</td><td>Provider identifier</td></tr></tbody></table><hr><h2 id="_5-fallback-behavior" tabindex="-1">5. Fallback Behavior <a class="header-anchor" href="#_5-fallback-behavior" aria-label="Permalink to &quot;5. Fallback Behavior&quot;">​</a></h2><p>When <code>normalize_output(..., allow_fallback=True)</code>:</p><ol><li>Try registered adapter (XMLOutputAdapter for primary providers)</li><li>If parse_truncated → return adapter result (do not fall back)</li><li>If adapter fails or no tags → fallback to <code>extract_condensed</code> with <code>source_contract=fallback-plain</code>, confidence 0.3–0.5</li><li>If <code>allow_fallback=False</code> → raise <code>SemanticValidationError</code></li></ol><hr><h2 id="_6-implementation-reference" tabindex="-1">6. Implementation Reference <a class="header-anchor" href="#_6-implementation-reference" aria-label="Permalink to &quot;6. Implementation Reference&quot;">​</a></h2><ul><li>undefined<strong>Adapters:</strong> <code>src/thegent/contracts/adapters.py</code></li><li>undefined<strong>Registry:</strong> <code>ADAPTER_REGISTRY</code>, <code>get_adapter</code>, <code>register_adapter</code></li><li>undefined<strong>Normalization:</strong> <code>normalize_output(provider, raw, context, allow_fallback)</code></li><li>undefined<strong>CSM schema:</strong> <code>src/thegent/contracts/csm.py</code></li><li>undefined<strong>Parser:</strong> <code>src/thegent/contracts/parser.py</code> (IncrementalXMLParser)</li></ul><hr><h2 id="_7-conformance" tabindex="-1">7. Conformance <a class="header-anchor" href="#_7-conformance" aria-label="Permalink to &quot;7. Conformance&quot;">​</a></h2><ul><li>Run <code>thegent govern conformance</code> for adapter conformance suite</li><li>Run <code>thegent govern conformance --check-drift</code> for drift alarms</li><li>See <code>docs/contracts/FALLBACK_POLICY.md</code> for policy and observability</li></ul><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li><li><a href="./FALLBACK_POLICY.html">FALLBACK_POLICY.md</a> — fallback policy</li></ul>`,40)])])}const _=e(d,[["render",n]]);export{g as __pageData,_ as default};
